```json
{
  "root_causes": [
    {
      "service": "ts-route-plan-service",
      "fault_kind": "application_method_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'abn' p, span_name, count(*) n, round(quantile_cont(duration,0.5)/1e6,1) p50_ms, round(quantile_cont(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE service_name='ts-route-plan-service' AND attr_span_kind='Internal' AND span_name LIKE 'RoutePlanController%' GROUP BY 1,2 UNION ALL SELECT 'norm', span_name, count(*), round(quantile_cont(duration,0.5)/1e6,1), round(quantile_cont(duration,0.95)/1e6,1) FROM normal_traces WHERE service_name='ts-route-plan-service' AND attr_span_kind='Internal' AND span_name LIKE 'RoutePlanController%' GROUP BY 1,2 ORDER BY 2,1",
          "claim": "Route-plan's RoutePlanController self-time roughly doubled: getMinStopStations p50 318ms to 487ms, p95 669ms to 2658ms."
        },
        {
          "kind": "trace",
          "sql": "SELECT c.service_name callee_svc, c.span_name, count(*) n, round(quantile_cont(c.duration,0.5)/1e6,1) child_p50_ms FROM abnormal_traces p JOIN abnormal_traces c ON c.parent_span_id = p.span_id AND c.trace_id=p.trace_id WHERE p.service_name='ts-route-plan-service' AND p.attr_span_kind='Internal' AND p.span_name LIKE 'RoutePlanController%' GROUP BY 1,2 ORDER BY n DESC LIMIT 10",
          "claim": "Route-plan's downstream child calls (route, travel, travel2) stay at roughly 5–110ms p50, so the extra time is inside route-plan itself."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, attr_http_response_status_code code, count(*) n FROM abnormal_traces WHERE service_name='ts-route-plan-service' AND attr_http_response_status_code >= 500 GROUP BY 1,2,3,4 ORDER BY n DESC",
          "claim": "Route-plan returns HTTP 500 on minStopStations and cheapestRoute (32 each) and 503 on 64 client calls."
        },
        {
          "kind": "log",
          "sql": "SELECT service_name, level, substr(message,1,200) msg, count(*) n FROM abnormal_logs WHERE service_name='ts-route-plan-service' AND level NOT IN ('INFO','DEBUG') GROUP BY 1,2,3 ORDER BY n DESC",
          "claim": "Route-plan logs 64 SEVERE 'Request processing failed' exceptions wrapping a 503 from a downstream call; none in normal period."
        },
        {
          "kind": "metric",
          "sql": "SELECT metric, round(avg(value),3) avg_v, round(max(value),3) max_v FROM abnormal_metrics WHERE service_name='ts-route-plan-service' AND metric IN ('container.cpu.usage','k8s.pod.cpu_limit_utilization','k8s.pod.memory_limit_utilization') GROUP BY 1",
          "claim": "Route-plan container CPU usage and CPU-limit utilization stay low (about 0.09 and 0.02), so the slowdown is not container CPU exhaustion."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-route-plan-service",
      "to": "ts-travel-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name, p.span_name, count(*) n, sum(case when c.attr_http_response_status_code>=500 then 1 else 0 end) n_5xx, round(quantile_cont(c.duration,0.95)/1e6,1) child_p95_ms FROM abnormal_traces c JOIN abnormal_traces p ON p.span_id=c.parent_span_id AND p.trace_id=c.trace_id WHERE p.service_name='ts-travel-plan-service' AND p.attr_span_kind='Client' AND c.service_name='ts-route-plan-service' GROUP BY 1,2",
          "claim": "Travel-plan's client calls into route-plan return 500s and slow p95 latency during the incident."
        }
      ]
    },
    {
      "from": "ts-travel-plan-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, attr_http_response_status_code code, count(*) n, round(quantile_cont(duration,0.5)/1e6,1) p50_ms FROM abnormal_traces WHERE service_name IN ('ts-travel-plan-service','ts-ui-dashboard') AND attr_http_response_status_code >= 500 GROUP BY 1,2,3,4 ORDER BY n DESC",
          "claim": "Travel-plan server endpoints return 500 with p50 around 11–12 seconds, and the dashboard returns 503 errors on its travel2 endpoint."
        }
      ]
    }
  ]
}
```

